(6135002, 903921, 110041, '<td valign="top">Good oxymoron and good attempt to illustrate it using perspective. Shame the street isn''t quite long enough to show the buildings and road ''intersect'' but between the title and shot, I get the idea.<br/> <br/>Exposure is pretty good especially with such a bright sky. Good DoF. Perhaps you could crop an inch off the bottom of the photo.</td>', 'Good oxymoron and good attempt to illustrate it using perspective. Shame the street isn''t quite long enough to show the buildings and road ''intersect'' but between the title and shot, I get the idea. Exposure is pretty good especially with such a bright sky. Good DoF. Perhaps you could crop an inch off the bottom of the photo.', '2010-08-19 04:42:23.000000', NULL, 1),
(6135003, 903472, 110041, '<td valign="top">Great conveyance of the title.</td>', 'Great conveyance of the title.', '2010-08-19 04:42:59.000000', NULL, 1),
(6135005, 904072, 110041, '<td valign="top">Good theme (I was originally thinking of ''Stop Motion'' for my shot).<br/> <br/>It''s a bit of an awkward expression on her face, otherwise it would have been an excellent shot.<br/> <br/>A good effort nonetheless with good lighting on the face.</td>', 'Good theme (I was originally thinking of ''Stop Motion'' for my shot). It''s a bit of an awkward expression on her face, otherwise it would have been an excellent shot. A good effort nonetheless with good lighting on the face.', '2010-08-19 04:46:14.000000', NULL, 1),
(6135006, 903984, 110041, '<td valign="top">Good idea and pretty well executed with the DoF.<br/> <br/>If you could have gotten rid of the brown haired woman with the glasses in front so your subject wasn''t so hidden, it would have been an top shot.</td>', 'Good idea and pretty well executed with the DoF. If you could have gotten rid of the brown haired woman with the glasses in front so your subject wasn''t so hidden, it would have been an top shot.', '2010-08-19 04:47:39.000000', NULL, 1),
(6135008, 904134, 110041, '<td valign="top">Quite like this, but don''t know why. I do wonder if it would be better with all the poster in the frame?</td>', 'Quite like this, but don''t know why. I do wonder if it would be better with all the poster in the frame?', '2010-08-19 04:49:00.000000', NULL, 1),
(6135009, 903257, 110041, '<td valign="top">Good theme, good colours.</td>', 'Good theme, good colours.', '2010-08-19 04:50:46.000000', NULL, 1),
(6135010, 904132, 110041, '<td valign="top">Great shot. Love the muted tones and the bokeh.<br/> <br/>I can''t see how the the picture conveys the theme.</td>', 'Great shot. Love the muted tones and the bokeh. I can''t see how the the picture conveys the theme.', '2010-08-19 04:52:07.000000', NULL, 1),
(6135011, 903842, 110041, '<td valign="top">...and so the French surrendered, the war was over and the British were victorious.<br/> <br/>Extra points for historic accuracy ;^)</td>', '...and so the French surrendered, the war was over and the British were victorious. Extra points for historic accuracy ;^)', '2010-08-19 04:55:25.000000', NULL, 1),
(6135012, 903742, 110041, '<td valign="top">Tricky to mark because you''ve got the face nicely but the bat and ball are clearly not stopped!<br/> <br/>The lad''s also not watching the ball!</td>', 'Tricky to mark because you''ve got the face nicely but the bat and ball are clearly not stopped! The lad''s also not watching the ball!', '2010-08-19 04:57:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6135014, 904165, 110041, '<td valign="top">You''ve depicted a very dark and sombre scene. I think the editting has certainly made it one of the more emotive shots in the challenge.<br/> <br/>Unfortunately, the title really doesn''t reflect that mood.<br/> <br/>That said, the picture does convey the message that a cat really isn''t domesticated.</td>', 'You''ve depicted a very dark and sombre scene. I think the editting has certainly made it one of the more emotive shots in the challenge. Unfortunately, the title really doesn''t reflect that mood. That said, the picture does convey the message that a cat really isn''t domesticated.', '2010-08-19 05:05:57.000000', NULL, 1),
